<script setup lang="ts">
import {ref} from 'vue';import {write,newKey} from '../../../../packages/shared/src/client';import {useTask} from '../../../../packages/shared/src/ui';import Status from '../../../../packages/shared/src/Status.vue';
const task=useTask(),id=ref(''),begin=ref(''),end=ref(''),days=ref(30);
async function issue(){await task.run(async()=>{await write('/admin/promotion/coupons/'+id.value+'/issue','PUT',{id:id.value,issueBeginTime:begin.value||undefined,issueEndTime:end.value,termDays:days.value},newKey());task.message.value='发放计划已保存';});}
</script><template><section class="card"><h2>发放优惠券</h2><Status :busy="task.busy.value" :error="task.error.value" :message="task.message.value"/><el-form label-width="120px"><el-form-item label="优惠券 ID"><el-input v-model="id"/></el-form-item><el-form-item label="发放开始"><el-date-picker v-model="begin" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss"/></el-form-item><el-form-item label="发放结束"><el-date-picker v-model="end" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss"/></el-form-item><el-form-item label="领取后有效天数"><el-input-number v-model="days" :min="1" :max="3650"/></el-form-item><el-button type="primary" @click="issue" :disabled="!id || !end || task.busy.value">保存发放计划</el-button></el-form></section></template>